<template>
  <section class="pre-archive-matrix" :class="{compact,'is-disabled':disabled}">
    <fieldset class="matrix-fields" :disabled="disabled">
      <PreOrderRequirements :item="item" :disabled="disabled||!!pendingRemoval" />
      <div class="matrix-toolbar" :inert="disabled||!!pendingRemoval">
        <div class="matrix-axis"><label>颜色</label><OrderAxisSelect :key="selectorVersion+'-colors'" :model-value="colors" :options="colorOptions" :sort-names="sortColorNames" label="颜色" kind="colors" :max="60" @update:model-value="requestAxis('colors',$event)"/><button type="button" class="matrix-link" @click="configure('colors')">管理</button></div>
        <div class="matrix-axis matrix-size-axis"><label>尺码</label><OrderAxisSelect :key="selectorVersion+'-sizes'" :model-value="sizes" :options="sizeOptions" :sort-names="sortSizeNames" label="尺码" kind="sizes" :max="30" @update:model-value="requestAxis('sizes',$event)"/><div class="matrix-template-links"><button type="button" class="matrix-link" @click="configure('sizes')">管理</button><button type="button" class="matrix-link" @click="templateOpen=true">选择模板</button><button type="button" class="matrix-link" :disabled="!sizes.length" @click="openSaveTemplate()">保存模板</button></div></div>
        <div class="matrix-toggles"><label>行复制<button type="button" class="matrix-switch" :class="{on:rowCopy}" role="switch" aria-label="行复制" :aria-checked="rowCopy" @click="toggleCopy('row')"><span/></button></label><label>列复制<button type="button" class="matrix-switch" :class="{on:colCopy}" role="switch" aria-label="列复制" :aria-checked="colCopy" @click="toggleCopy('column')"><span/></button></label><label>分码分色分价<button type="button" class="matrix-switch" :class="{on:splitPrice}" role="switch" aria-label="分码分色分价" :aria-checked="splitPrice" @click="changePricingMode()"><span/></button></label></div>
        <label class="matrix-currency">默认币种<span>美元 <small>USD</small></span></label>
      </div>
      <p v-if="rowCopy||colCopy" class="matrix-copy-hint">点击格内复制图标，将该格{{splitPrice?'数量和单价':'数量'}}复制到{{rowCopy?'同一颜色的全部尺码':'同一尺码的全部颜色'}}。</p>
      <div v-if="pendingRemoval" class="matrix-removal" role="alert"><div><strong>确认移除{{pendingRemoval.label}}：{{pendingRemoval.names.map(n=>n||'待确认').join('、')}}？</strong><p>将删除 {{pendingRemoval.cells}} 格已填报价<span v-if="pendingRemoval.pictures">和 {{pendingRemoval.pictures}} 张颜色图片</span>。取消可保留原数据。</p></div><button type="button" @click="cancelRemoval()">取消</button><button type="button" class="danger" @click="confirmRemoval()">确认移除</button></div>
      <p v-if="message" class="matrix-message" role="status">{{message}}</p>
      <div class="matrix-color-pictures" :inert="disabled||!!pendingRemoval"><b>颜色图片</b><div v-if="colors.length" class="matrix-picture-strip"><div v-for="color in colors" :key="color"><span>{{color||'待确认'}}</span><ImageUpload hover-paste :model-value="colorImages[color]||''" :disabled="disabled||!!pendingRemoval" :title="(color||'待确认')+'颜色图片'" size="sm" @update:model-value="setColorImage(color,$event)" @uploading="trackUpload($event)"/><small>支持粘贴 / 拖入</small></div></div><p v-else>选择颜色后可分别添加图片。</p></div>
      <div class="matrix-main" :inert="disabled||!!pendingRemoval">
        <aside v-if="showProduct&&!hideProduct"><img v-if="item.effect_image_url" :src="item.effect_image_url" :alt="item.product_name||item.style_no||'款式图片'" @click="openImage(item.effect_image_url,item.style_no)"/><span v-else class="matrix-no-image">暂无图片</span><b>{{item.style_no||item.product_name}}</b><small v-if="item.style_no&&item.product_name!==item.style_no">{{item.product_name}}</small></aside>
        <div class="matrix-scroll"><table v-if="colors.length&&sizes.length" :class="{'split-pricing':splitPrice,'has-copy':rowCopy||colCopy}"><thead><tr><th>颜色 / 尺码</th><th v-for="size in sizes" :key="size">{{size}}</th><th class="matrix-total matrix-sticky" :title="splitPrice?'数量 / 金额（USD）':'数量合计'">合计<span v-if="splitPrice" class="matrix-total-label">数量 / 金额</span></th></tr><tr class="customer-size-row"><th>客户尺码</th><th v-for="size in sizes" :key="size"><input :aria-label="size+'客户尺码'" :value="rows.find(row=>row.size===size)?.customer_size||''" maxlength="50" placeholder="客户尺码" @input="setCustomerSize(size,$event.target.value)"/></th><th class="matrix-sticky"/></tr><tr class="matrix-value-labels"><th>录入内容</th><th v-for="size in sizes" :key="size"><div class="matrix-cell-pair"><span>数量</span><span v-if="splitPrice">单价 USD</span><span v-if="rowCopy||colCopy" class="copy-label">复制</span></div></th><th class="matrix-sticky">{{splitPrice?'数量 / 金额 USD':'数量'}}</th></tr></thead>
          <tbody><tr v-for="color in colors" :key="color"><th>{{color||'待确认'}}</th><td v-for="size in sizes" :key="size"><div class="matrix-cell-pair"><input class="matrix-qty" :aria-label="(color||'待确认')+' '+size+'数量'" title="数量" type="number" min="0" max="1000000" step="1" :value="cell(color,size)?.qty||0" @input="setQty(color,size,$event.target.value)"/><input v-if="splitPrice" class="matrix-cell-price" :aria-label="(color||'待确认')+' '+size+'单价'" title="单价（USD）" type="number" min="0" step="0.01" :value="cell(color,size)?.unit_price||0" @input="setPrice(color,size,$event.target.value)"/><button v-if="rowCopy||colCopy" type="button" class="matrix-copy-btn" :aria-label="(color||'待确认')+' '+size+' 复制到本'+(rowCopy?'行':'列')" :title="'将此格'+(splitPrice?'数量和单价':'数量')+'复制到本'+(rowCopy?'行':'列')" :disabled="(rowCopy?sizes.length:colors.length)<2" @click="copyCell(color,size)"><svg viewBox="0 0 18 18" width="16" height="16" aria-hidden="true"><rect x="6" y="2" width="9" height="11" rx="1.5"/><rect x="3" y="5" width="9" height="11" rx="1.5"/><path v-if="rowCopy" d="M5 10h5m-2-2 2 2-2 2"/><path v-else d="M7.5 8v5m-2-2 2 2 2-2"/></svg></button></div></td><td class="matrix-total matrix-sticky" :title="totalDescription(rowTotals[color])" :aria-label="(color||'待确认')+'合计，'+totalDescription(rowTotals[color])">{{totalText(rowTotals[color])}}</td></tr></tbody>
          <tfoot><tr><th>合计</th><td v-for="size in sizes" :key="size" class="matrix-total" :title="totalDescription(sizeTotals[size])" :aria-label="size+'合计，'+totalDescription(sizeTotals[size])">{{totalText(sizeTotals[size])}}</td><td class="matrix-total matrix-sticky" :title="totalDescription(totalSummary)" :aria-label="'总计，'+totalDescription(totalSummary)">{{totalText(totalSummary)}}</td></tr></tfoot></table>
          <p v-else class="matrix-empty">{{!colors.length&&!sizes.length?'请选择颜色和尺码后填写数量。':!colors.length?'已选好尺码，请继续选择颜色。':'已选好颜色，请继续选择尺码或尺码模板。'}}</p>
        </div>
      </div>
      <footer class="matrix-footer" :inert="disabled||!!pendingRemoval"><button v-if="showRemove" type="button" class="matrix-link danger" @click="$emit('remove')">删除商品</button><label v-if="!splitPrice">销售单价 <input aria-label="销售单价 USD" type="number" min="0" step="0.01" :disabled="!rows.length" :value="defaultPrice" @input="uniformPrice($event.target.value)"/></label><label>币种 <span class="matrix-currency-value">美元 USD</span></label><span class="matrix-summary">下单数量 <b>{{totalQty}}</b></span><span class="matrix-summary">商品金额 USD <b>{{amount.toFixed(2)}}</b></span></footer>
      <PreOrderMaterialDetails :item="item" :disabled="disabled" @uploading="trackUpload" />
      <div v-if="edit.open" class="matrix-dialog-mask"><section class="matrix-dialog" role="dialog" aria-modal="true" :aria-label="'管理'+(edit.kind==='colors'?'颜色':'尺码')"><h3>管理{{edit.kind==='colors'?'颜色':'尺码'}}</h3><p>每行一个，仅影响本单。移除已有报价或图片时需要确认。</p><textarea v-model="edit.text" rows="10" :aria-label="(edit.kind==='colors'?'颜色':'尺码')+'列表'"/><footer><button type="button" @click="edit.open=false">取消</button><button type="button" class="primary" @click="applyConfig()">确定</button></footer></section></div>
      <div v-if="templateOpen" class="matrix-dialog-mask"><section class="matrix-dialog" role="dialog" aria-modal="true" aria-label="选择尺码模板"><h3>选择尺码模板</h3><p>模板尺码会加入当前所选尺码，并按尺码顺序排列。</p><div class="matrix-template-list"><button v-for="template in templates" :key="template.id" type="button" @click="chooseTemplate(template)"><b>{{template.name}}</b><small>{{templateSizeNames(template).join('、')}}</small></button><p v-if="!templates.length">暂无模板，可先选择尺码再保存模板。</p></div><footer><button type="button" @click="templateOpen=false">关闭</button></footer></section></div>
      <div v-if="templateSave.open" class="matrix-dialog-mask"><section class="matrix-dialog" role="dialog" aria-modal="true" aria-label="保存尺码模板"><h3>保存尺码模板</h3><label>模板名称<input v-model="templateSave.name" maxlength="80" placeholder="输入模板名称" :disabled="templateSave.busy" @keydown.enter.stop.prevent="saveTemplate()"/></label><p>{{sizes.join('、')}}</p><p v-if="templateSave.error" class="matrix-message">{{templateSave.error}}</p><footer><button type="button" :disabled="templateSave.busy" @click="templateSave.open=false">取消</button><button type="button" class="primary" :disabled="templateSave.busy" @click="saveTemplate()">{{templateSave.busy?'保存中…':'保存'}}</button></footer></section></div>
    </fieldset>
  </section>
</template>
<script setup>
import {computed,reactive,ref,watch,onBeforeUnmount} from 'vue';
import {api} from '../api';
import {orderColorOptions} from '../utils/orderOptions';
import {sortColorNames,sortSizeNames,orderSizeOptions,templateSizeNames,reconcileQuoteMatrix,removedQuoteCells,hasQuoteData,readQuoteMatrixMeta,applyQuoteField,copyQuoteCell,quoteTotals} from '../utils/orderAxes';
import {openImage} from '../store/viewer';
import OrderAxisSelect from './OrderAxisSelect.vue';
import ImageUpload from './ImageUpload.vue';
import PreOrderRequirements from './PreOrderRequirements.vue';
import PreOrderMaterialDetails from './PreOrderMaterialDetails.vue';
const props=defineProps({item:{type:Object,required:true},templates:{type:Array,default:()=>[]},compact:Boolean,hideProduct:Boolean,showProduct:{type:Boolean,default:true},showRemove:{type:Boolean,default:true},disabled:Boolean});
const emit=defineEmits(['remove','uploading','templates-changed']);
const colors=ref([]),sizes=ref([]),extraSizes=ref([]),extraColors=ref([]),colorImages=ref({}),splitPrice=ref(false),defaultPrice=ref(0),pendingRemoval=ref(null),message=ref(''),selectorVersion=ref(0),rowCopy=ref(false),colCopy=ref(false),templateOpen=ref(false),uploadCount=ref(0);
const edit=reactive({open:false,kind:'',text:''}),templateSave=reactive({open:false,name:'',busy:false,error:''});
let locallyAssignedRows=null,locallyAssignedMeta=null,unmounted=false;
const rows=computed(()=>props.item.size_prices||[]);
const colorOptions=computed(()=>sortColorNames([...orderColorOptions,...extraColors.value,...colors.value]));
const sizeOptions=computed(()=>sortSizeNames([...orderSizeOptions,...extraSizes.value,...sizes.value]));
const cell=(color,size)=>rows.value.find(row=>(row.color||'')===color&&row.size===size);
const totalSummary=computed(()=>quoteTotals(rows.value));
const totalQty=computed(()=>totalSummary.value.qty),amount=computed(()=>totalSummary.value.cents/100);
const rowTotals=computed(()=>Object.fromEntries(colors.value.map(color=>[color,quoteTotals(rows.value.filter(row=>(row.color||'')===color))])));
const sizeTotals=computed(()=>Object.fromEntries(sizes.value.map(size=>[size,quoteTotals(rows.value.filter(row=>row.size===size))])));
const totalText=total=>splitPrice.value?`${total.qty} / ${(total.cents/100).toFixed(2)}`:String(total.qty);
const totalDescription=total=>`数量 ${total.qty}，金额 USD ${(total.cents/100).toFixed(2)}`;
function sync(){props.item.expected_qty=totalQty.value;}
function syncMeta(){props.item.matrix_meta={...props.item.matrix_meta,colors:[...colors.value],sizes:[...sizes.value],color_images:Object.fromEntries(colors.value.filter(color=>Object.hasOwn(colorImages.value,color)&&colorImages.value[color]).map(color=>[color,colorImages.value[color]])),split_price:splitPrice.value};locallyAssignedMeta=props.item.matrix_meta;}
function adoptRows(reset=false){const meta=readQuoteMatrixMeta(rows.value,props.item.matrix_meta);colors.value=meta.colors;sizes.value=meta.sizes;colorImages.value=meta.color_images;splitPrice.value=meta.split_price;defaultPrice.value=Number(rows.value[0]?.unit_price||0);if(reset){extraSizes.value=[];extraColors.value=[];pendingRemoval.value=null;message.value='';rowCopy.value=false;colCopy.value=false;edit.open=false;templateOpen.value=false;selectorVersion.value++;}}
watch(()=>props.item,()=>{locallyAssignedRows=null;locallyAssignedMeta=null;adoptRows(true);},{immediate:true});
watch(()=>[props.item.size_prices,props.item.matrix_meta],([nextRows,nextMeta],[previousRows,previousMeta])=>{if(nextRows!==previousRows&&nextRows!==locallyAssignedRows||nextMeta!==previousMeta&&nextMeta!==locallyAssignedMeta)adoptRows();});
function applyAxes(nextColors,nextSizes){colors.value=nextColors;sizes.value=nextSizes;extraColors.value=sortColorNames([...extraColors.value,...nextColors]);extraSizes.value=sortSizeNames([...extraSizes.value,...nextSizes]);props.item.size_prices=reconcileQuoteMatrix(rows.value,nextColors,nextSizes,{defaultPrice:defaultPrice.value,splitPrice:splitPrice.value});locallyAssignedRows=props.item.size_prices;colorImages.value=Object.fromEntries(nextColors.filter(color=>Object.hasOwn(colorImages.value,color)&&colorImages.value[color]).map(color=>[color,colorImages.value[color]]));sync();syncMeta();}
function requestAxis(kind,names){
  if(props.disabled||pendingRemoval.value)return false;
  message.value='';const next=kind==='colors'?sortColorNames(names):sortSizeNames(names),limit=kind==='colors'?60:30,maxLength=kind==='colors'?100:50;
  if(next.length>limit||next.some(name=>name.length>maxLength)){message.value=`${kind==='colors'?'颜色':'尺码'}最多${limit}项，名称最多${maxLength}字`;return false;}
  const nextColors=kind==='colors'?next:colors.value,nextSizes=kind==='sizes'?next:sizes.value,removed=removedQuoteCells(rows.value,nextColors,nextSizes).filter(hasQuoteData),pictures=colors.value.filter(color=>!nextColors.includes(color)&&colorImages.value[color]).length;
  if(removed.length||pictures){pendingRemoval.value={colors:nextColors,sizes:nextSizes,label:kind==='colors'?'颜色':'尺码',names:(kind==='colors'?colors.value:sizes.value).filter(name=>!next.includes(name)),cells:removed.length,pictures};selectorVersion.value++;return true;}
  applyAxes(nextColors,nextSizes);return true;
}
function cancelRemoval(){pendingRemoval.value=null;}
function confirmRemoval(){if(props.disabled||!pendingRemoval.value)return;const next=pendingRemoval.value;pendingRemoval.value=null;applyAxes(next.colors,next.sizes);}
function setCustomerSize(size,value){if(props.disabled||pendingRemoval.value)return;rows.value.filter(row=>row.size===size).forEach(row=>row.customer_size=value);}
function editCell(color,size,field,value){if(props.disabled||pendingRemoval.value)return;applyQuoteField(rows.value,color,size,field,value);if(field==='qty')sync();}
function copyCell(color,size){if(props.disabled||pendingRemoval.value)return;const mode=rowCopy.value?'row':colCopy.value?'column':'';const count=copyQuoteCell(rows.value,color,size,mode,{splitPrice:splitPrice.value});if(!count)return;sync();message.value='已将 '+(color||'待确认')+' / '+size+' 的'+(splitPrice.value?'数量和单价':'数量')+'复制到本'+(rowCopy.value?'行':'列')+'其余 '+count+' 格。';}
function setQty(color,size,value){editCell(color,size,'qty',value);}
function setPrice(color,size,value){editCell(color,size,'unit_price',value);}
function uniformPrice(value){if(props.disabled||pendingRemoval.value)return;defaultPrice.value=value===''?0:Number(value);rows.value.forEach(row=>row.unit_price=defaultPrice.value);}
function changePricingMode(){if(props.disabled||pendingRemoval.value)return;if(splitPrice.value&&new Set(rows.value.map(row=>Number(row.unit_price||0))).size>1){message.value='当前颜色尺码单价不同，请核对单价一致后再关闭分价。';return;}splitPrice.value=!splitPrice.value;if(!splitPrice.value&&rows.value.length)defaultPrice.value=Number(rows.value[0].unit_price||0);message.value='';syncMeta();}
function toggleCopy(kind){if(props.disabled||pendingRemoval.value)return;message.value='';if(kind==='row'){rowCopy.value=!rowCopy.value;if(rowCopy.value)colCopy.value=false;}else{colCopy.value=!colCopy.value;if(colCopy.value)rowCopy.value=false;}}
function setColorImage(color,value){if(!colors.value.includes(color)||props.disabled&&!uploadCount.value)return;colorImages.value={...colorImages.value,[color]:value};syncMeta();}
function trackUpload(active){if(unmounted)return;const previous=uploadCount.value;uploadCount.value=Math.max(0,previous+(active?1:-1));if(!previous&&uploadCount.value)emit('uploading',true);else if(previous&&!uploadCount.value)emit('uploading',false);}
onBeforeUnmount(()=>{unmounted=true;if(uploadCount.value)emit('uploading',false);});
function configure(kind){if(props.disabled||pendingRemoval.value)return;Object.assign(edit,{open:true,kind,text:(kind==='colors'?colors.value:sizes.value).join('\n')});}
function applyConfig(){if(requestAxis(edit.kind,edit.text.split(/[\n,，]/u).map(value=>value.trim()).filter(Boolean)))edit.open=false;}
function chooseTemplate(template){if(requestAxis('sizes',[...sizes.value,...templateSizeNames(template)]))templateOpen.value=false;}
function openSaveTemplate(){if(props.disabled||!sizes.value.length)return;Object.assign(templateSave,{open:true,name:'',busy:false,error:''});}
async function saveTemplate(){if(templateSave.busy||props.disabled)return;const name=templateSave.name.trim();if(!name){templateSave.error='请输入模板名称';return;}if(!sizes.value.length){templateSave.error='请先选择尺码';return;}templateSave.busy=true;templateSave.error='';try{await api.createSizeTemplate({name,sizes:[...sizes.value]});emit('templates-changed');templateSave.open=false;message.value='尺码模板已保存';}catch(error){templateSave.error=error.message||'保存失败，请重试';}finally{templateSave.busy=false;}}
</script>
<style scoped>
.matrix-value-labels span{flex:1;font-size:11px;color:var(--ink-soft);font-weight:normal}.matrix-value-labels .copy-label{flex:0 0 22px}

.pre-archive-matrix{--entry-blue:#1890ff;--entry-line:var(--line);--matrix-accent:var(--entry-blue);background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:4px;padding:12px 15px;margin:12px 0;min-width:0}.pre-archive-matrix.compact{padding:10px;margin:8px 0}.matrix-fields{border:0;padding:0;margin:0;min-width:0}.matrix-toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;min-height:60px}.matrix-axis{display:flex;align-items:center;gap:8px;min-width:0}.matrix-axis>label{font-size:12px;color:var(--ink-soft);white-space:nowrap}.matrix-template-links{display:flex;gap:5px;white-space:nowrap}.matrix-link{border:0;background:none;color:var(--matrix-accent);padding:2px 0;font-size:12px;white-space:nowrap;cursor:pointer}.matrix-link:disabled{opacity:.5;cursor:default}.matrix-toggles{display:flex;align-items:center;gap:13px}.matrix-toggles label,.matrix-currency{display:flex;gap:7px;align-items:center;font-size:12px;color:var(--ink-soft);white-space:nowrap}.matrix-switch{display:inline-flex;align-items:center;width:38px;height:20px;border:0;background:var(--line);border-radius:12px;padding:3px;cursor:pointer;flex:none}.matrix-switch span{height:14px;width:14px;border-radius:50%;background:var(--surface);box-shadow:0 1px 2px #0002}.matrix-switch.on{background:var(--matrix-accent);justify-content:flex-end}.matrix-currency>span,.matrix-currency-value{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--line);border-radius:3px;background:var(--surface);padding:5px 10px;min-height:27px;box-sizing:border-box}.matrix-currency small{font-size:10px;color:var(--ink-mute)}
